// Ошибка — это объект с name, message, stack
// try — пробуем выполнить код, который может упасть
try {
  // Этот код может выбросить ошибку
  const result = 10 / 0;
  console.log(result);  // Infinity — но не ошибка!
} catch (error) {
  // Если в try что-то упало — ловим ошибку здесь
  console.error("Ошибка:", error.message);
} finally {
  // Этот блок выполняется ВСЕГДА — и при успехе, и при ошибке
  console.log("Конец операции");
}

try {
  // Парсим JSON — может быть невалидный
  const data = JSON.parse('{bad json}');
  console.log(data);  // НЕ выполнится!
} catch (error) {
  // JSON.parse выбросил SyntaxError — ловим
  console.error("Битый JSON:", error.message);
}

console.log("Программа продолжается");  // выполняется — ошибка поймана!

function divide(a, b) {
  if (b === 0) {
    // Выбрасываем ошибку — деление на ноль!
    throw new Error("Division by zero");
  }
  return a / b;  // только если b не ноль
}

try {
  console.log(divide(10, 2));  // 5 — ок
  console.log(divide(10, 0));  // ошибка — прыгаем в catch
  console.log("Это не выполнится");
} catch (error) {
  console.error("Поймана:", error.message);  // Division by zero
}

console.log("Программа продолжается");  // выполняется!

