// TypeError — вызываем метод у undefined
try {
  undefined.foo();
} catch (e) {
  console.log(e.name);  // TypeError
}

// ReferenceError — используем необъявленную переменную
try {
  console.log(nonexistent);
} catch (e) {
  console.log(e.name);  // ReferenceError
}

// RangeError — рекурсия без остановки
try {
  function recurse() { recurse(); }
  recurse();
} catch (e) {
  console.log(e.name);  // RangeError
}

// SyntaxError — при разборе кода
try {
  eval("bad code");
} catch (e) {
  console.log(e.name);  // SyntaxError

class ValidationError extends Error {
  constructor(message) {
    super(message);
    this.name = "ValidationError";
  }
}

class AuthError extends Error {
  constructor(message) {
    super(message);
    this.name = "AuthError";
  }
}

function login(username, password) {
  if (!username) throw new ValidationError("Username required");
  if (password.length < 8) throw new ValidationError("Password too short");
  if (password === "12345678") throw new AuthError("Too weak");
  return "Logged in";
}

try {
  login("", "password");
} catch (e) {
  if (e instanceof ValidationError) {
    console.log("Ошибка данных:", e.message);
  } else if (e instanceof AuthError) {
    console.log("Ошибка авторизации:", e.message);
  }
}

// ОПАСНО: пустой catch скрывает все ошибки
try {
  JSON.parse("{bad}");
} catch (e) {
  // Ничего не делаем — ошибка пропала!
  // Программа продолжает работать с неинициализированными данными
}

// ПРАВИЛЬНО: хотя бы логируем
try {
  JSON.parse("{bad}");
} catch (e) {
  console.error("Невалидный JSON:", e.message);
  // Показываем пользователю сообщение, используем fallback
  const data = null;
}

// ИЛИ: выбрасываем дальше
try {
  JSON.parse("{bad}");
} catch (e) {
  throw new Error("Failed to parse data: " + e.message);
}

// BAD: throw для 'нормального' случая
function find(arr, val) {
  if (!arr.includes(val)) {
    throw "Not found";  // нет — это не ошибка!
  }
  return arr.indexOf(val);
}

// GOOD: возвращаем null, если не нашли
function find(arr, val) {
  const idx = arr.indexOf(val);
  if (idx === -1) return null;  // null = 'не нашли'
  return idx;
}

// throw — только для НАСТОЯЩИХ проблем
function parseAge(str) {
  const age = Number(str);
  if (isNaN(age)) {
    throw new Error("Invalid age");  // это реально ошибка
  }
  return age;
}

try {
  // Внешний try — общая обработка
  try {
    // Внутренний try — детальная обработка
    const data = JSON.parse("{bad}");
  } catch (inner) {
    console.error("Битый JSON:", inner.message);
    throw inner;  // Перебрасываем дальше
  }
} catch (outer) {
  console.error("Общая ошибка:", outer.message);
  // Здесь можно показать пользователю
}

